'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const J = require('../js/jyotish.js');
const Daily = require('../js/daily.js');
const fixtures = require('./fixtures/lahiri-reference.json');
const YEAR = 365.25 * 86400000;
const ORDER = ['Кету', 'Венера', 'Солнце', 'Луна', 'Марс', 'Раху', 'Юпитер', 'Сатурн', 'Меркурий'];
const LENGTHS = [7, 20, 6, 10, 7, 18, 16, 19, 17];
const angularDifference = (a, b) => Math.abs(((a - b + 540) % 360) - 180);

// The expected values are independent Swiss Ephemeris output, not generated by
// the code under test. No personal birth records are included in these fixtures.
for (const fixture of fixtures.cases) {
  test('Lahiri coordinates match independent ephemeris: ' + fixture.id, () => {
    const chart = J.computeChart(fixture.params);
    assert.ok(angularDifference(chart.lagna.sidLon, fixture.expected.ascendant) < 1 / 60, 'ascendant differs by >= 1 arcminute');
    for (const [body, expected] of Object.entries(fixture.expected.planets)) {
      assert.ok(angularDifference(chart.planets[body].sidLon, expected) < 1 / 60, body + ' differs by >= 1 arcminute');
      assert.equal(chart.planets[body].house, (chart.planets[body].signIdx - chart.lagna.signIdx + 12) % 12 + 1);
    }
  });
}

test('transit results include the normalized longitude consumed by the UI', () => {
  const at = new Date('2026-10-18T09:00:00Z');
  const transit = J.transits(at);
  const positions = Daily.positions(+at);
  for (const body of Object.keys(transit)) {
    assert.ok(Number.isFinite(transit[body].sidLon), body + '.sidLon is missing');
    assert.ok(transit[body].sidLon >= 0 && transit[body].sidLon < 360);
    assert.equal(Math.floor(transit[body].sidLon / 30), transit[body].signIdx);
    assert.ok(angularDifference(transit[body].sidLon, positions[body]) < 1 / 60);
  }
});

test('Venus subperiod order is Venus, Sun, Moon, Mars, Rahu, Jupiter, Saturn, Mercury, Ketu', () => {
  const maha = J.vimshottari(220, new Date('2000-01-01T00:00:00Z'));
  const venus = maha.find(p => p.planet === 'Венера');
  assert.deepEqual(J.antardasha(maha, venus).map(p => p.planet), ['Венера', 'Солнце', 'Луна', 'Марс', 'Раху', 'Юпитер', 'Сатурн', 'Меркурий', 'Кету']);
});

// Independent arithmetic for a synthetic midpoint of Saturn's lunar segment.
// Nine and a half years of the 19-year period had elapsed at birth. Children
// must be partitioned over the complete 19 years, then clipped at birth.
function children(planet, start, years) {
  let current = start;
  const index = ORDER.indexOf(planet);
  return Array.from({ length: 9 }, (_, offset) => {
    const i = (index + offset) % 9;
    const duration = years * LENGTHS[i] / 120;
    const node = { planet: ORDER[i], start: current, end: current + duration * YEAR, years: duration };
    current = node.end;
    return node;
  });
}
const syntheticBirth = Date.parse('2000-01-01T00:00:00Z');
const canonicalStart = syntheticBirth - 9.5 * YEAR;
const expectedAd = children('Сатурн', canonicalStart, 19).find(n => n.start <= syntheticBirth && syntheticBirth < n.end);
const expectedPd = children(expectedAd.planet, expectedAd.start, expectedAd.years).find(n => n.start <= syntheticBirth && syntheticBirth < n.end);

test('first partial major period retains the original subperiod boundaries', () => {
  const maha = J.vimshottari(220, new Date(syntheticBirth));
  const antar = J.antardasha(maha, maha[0]);
  assert.equal(antar[0].planet, expectedAd.planet);
  assert.equal(+antar[0].start, syntheticBirth);
  assert.ok(Math.abs(+antar[0].end - expectedAd.end) <= 2);
  assert.equal(+antar.at(-1).end, +maha[0].end);
});

test('daily microperiod at birth is not restarted or compressed', () => {
  const tree = Daily.buildDashaTree(220, syntheticBirth);
  const current = Daily.dashaAt(tree, syntheticBirth);
  assert.equal(current.md.planet, 'Сатурн');
  assert.equal(current.ad.planet, expectedAd.planet);
  assert.equal(current.pd.planet, expectedPd.planet);
  assert.ok(Math.abs(current.ad.end - expectedAd.end) <= 2);
  assert.ok(Math.abs(current.pd.end - expectedPd.end) <= 2);
});

test('core and daily trees agree on all visible subperiod boundaries', () => {
  const birth = new Date(syntheticBirth);
  const major = J.vimshottari(220, birth);
  const daily = Daily.buildDashaTree(220, +birth);
  for (let i = 0; i < major.length; i++) {
    const expected = J.antardasha(major, major[i]);
    assert.equal(daily[i].antar.length, expected.length);
    assert.equal(daily[i].start, +major[i].start);
    assert.equal(daily[i].end, +major[i].end);
    expected.forEach((ad, j) => {
      assert.equal(daily[i].antar[j].planet, ad.planet);
      assert.equal(daily[i].antar[j].start, +ad.start);
      assert.equal(daily[i].antar[j].end, +ad.end);
    });
  }
});

test('daily periods are continuous and choose the next node at a boundary', () => {
  const tree = Daily.buildDashaTree(220, syntheticBirth);
  for (const md of tree) {
    assert.equal(md.antar[0].start, md.start);
    assert.equal(md.antar.at(-1).end, md.end);
    for (let i = 0; i < md.antar.length; i++) {
      const ad = md.antar[i];
      assert.ok(ad.end > ad.start);
      if (i) assert.equal(md.antar[i - 1].end, ad.start);
      assert.equal(ad.pratyantar[0].start, ad.start);
      assert.equal(ad.pratyantar.at(-1).end, ad.end);
      for (let j = 0; j < ad.pratyantar.length; j++) {
        const pd = ad.pratyantar[j];
        if (j) assert.equal(ad.pratyantar[j - 1].end, pd.start);
        assert.equal(Daily.dashaAt(tree, pd.start).pd, pd);
      }
    }
  }
});


test('period clipping remains contiguous across all nine starting lords', () => {
  for (let nakshatra = 0; nakshatra < 27; nakshatra++) {
    for (const fraction of [0, 0.125, 0.5, 0.875, 0.999]) {
      const moon = (nakshatra + fraction) * (360 / 27);
      const tree = Daily.buildDashaTree(moon, syntheticBirth);
      assert.equal(tree[0].start, syntheticBirth);
      for (const md of tree) {
        assert.equal(md.antar[0].start, md.start);
        assert.equal(md.antar.at(-1).end, md.end);
        for (let i = 0; i < md.antar.length; i++) {
          const ad = md.antar[i];
          if (i) assert.equal(md.antar[i - 1].end, ad.start);
          assert.equal(ad.pratyantar[0].start, ad.start);
          assert.equal(ad.pratyantar.at(-1).end, ad.end);
          for (let k = 0; k < ad.pratyantar.length; k++) {
            if (k) assert.equal(ad.pratyantar[k - 1].end, ad.pratyantar[k].start);
            assert.ok(ad.pratyantar[k].end > ad.pratyantar[k].start);
          }
        }
      }
    }
  }
});
